import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] parent = new int[n];
        long[] sub = new long[n];
        for (int i = 0; i < n; i++) parent[i] = nextInt();
        for (int i = 0; i < n; i++) sub[i] = nextLong();
        // parents have smaller ids, so reverse order finishes every subtree before its parent
        for (int i = n - 1; i > 0; i--) sub[parent[i]] += sub[i];
        long best = Long.MAX_VALUE;
        for (int i = 1; i < n; i++) best = Math.min(best, Math.abs(sub[0] - 2 * sub[i]));
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n := readInt()
	parent := make([]int, n)
	sub := make([]int, n)
	for i := range parent {
		parent[i] = readInt()
	}
	for i := range sub {
		sub[i] = readInt()
	}
	// parents have smaller ids, so reverse order finishes every subtree before its parent
	for i := n - 1; i > 0; i-- {
		sub[parent[i]] += sub[i]
	}
	best := -1
	for i := 1; i < n; i++ {
		d := sub[0] - 2*sub[i]
		if d < 0 {
			d = -d
		}
		if best < 0 || d < best {
			best = d
		}
	}
	fmt.Println(best)
}
